import random, itertools, math

n = 17
target_edges = 28

def has_short_cycle(adj, max_len=5):
    """Check if graph has a cycle of length <= max_len"""
    for s in range(n):
        # BFS
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            v = queue.pop(0)
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    parent[w] = v
                    queue.append(w)
                elif w != parent[v]:
                    cycle_len = dist[v] + dist[w] + 1
                    if cycle_len <= max_len:
                        return True, cycle_len
    return False, None

def is_4_colorable(adj):
    """Check if graph is 4-colorable using backtracking"""
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for w in adj[v]:
            if colors[w] != -1:
                used.add(colors[w])
        for c in range(4):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0), colors

# Try random bipartite graphs with no C4
best_edges = 0
best_adj = None
best_colors = None

for trial in range(100000):
    # Random bipartition
    vertices = list(range(n))
    random.shuffle(vertices)
    k = random.randint(7, 10)
    left = set(vertices[:k])
    right = set(vertices[k:])

    adj = {v: set() for v in range(n)}
    edges = []

    # Try to add edges without creating 4-cycles
    possible = [(u,v) for u in left for v in right]
    random.shuffle(possible)

    for u,v in possible:
        # Check if adding this edge creates a 4-cycle
        # A 4-cycle would be u - v - u' - v' - u where u,u' in left, v,v' in right
        # So we need to check if there exists u' in left, v' in right such that
        # u' connected to v and u connected to v'
        creates_c4 = False
        for u2 in left:
            if u2 == u: continue
            if v in adj[u2]:
                for v2 in adj[u]:
                    if v2 in right and v2 != v and v2 in adj[u2]:
                        creates_c4 = True
                        break
            if creates_c4:
                break
        if not creates_c4:
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))

    if len(edges) > best_edges:
        best_edges = len(edges)
        best_adj = adj
        print(f"Trial {trial}: {len(edges)} edges")

        if len(edges) >= target_edges:
            # Check girth
            has_short, cycle_len = has_short_cycle(adj, 5)
            if not has_short:
                # Check 4-colorability
                colorable, colors = is_4_colorable(adj)
                if colorable:
                    print(f"Found! Edges: {len(edges)}")
                    print(f"Edges list: {edges}")
                    print(f"Colors: {colors}")
                    break
                else:
                    print(f"  Not 4-colorable")
            else:
                print(f"  Has short cycle of length {cycle_len}")

print(f"Best edges found: {best_edges}")

