import itertools
from z3 import *

n = 17
min_edges = 28

# Create boolean variables for edges
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = Bool(f'e_{i}_{j}')

solver = Solver()

# At least min_edges edges
solver.add(AtLeast(*list(edge_vars.values()), min_edges))

# Forbid triangles (3-cycles)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(edge_vars[(i,j)], edge_vars[(i,k)], edge_vars[(j,k)])))

print("Added triangle constraints")

# Forbid 4-cycles - but we can be smarter: a 4-cycle is a,b,c,d with edges (a,b),(b,c),(c,d),(d,a)
# We can enumerate all 4-tuples of distinct vertices
count = 0
for a in range(n):
    for b in range(n):
        if b == a: continue
        for c in range(n):
            if c == a or c == b: continue
            for d in range(n):
                if d == a or d == b or d == c: continue
                e1 = edge_vars[(a,b) if a<b else (b,a)]
                e2 = edge_vars[(b,c) if b<c else (c,b)]
                e3 = edge_vars[(c,d) if c<d else (d,c)]
                e4 = edge_vars[(d,a) if d<a else (a,d)]
                solver.add(Not(And(e1, e2, e3, e4)))
                count += 1
print(f"Added {count} 4-cycle constraints")

# Forbid 5-cycles - this is a lot but let's try
count = 0
for a in range(n):
    for b in range(n):
        if b == a: continue
        for c in range(n):
            if c == a or c == b: continue
            for d in range(n):
                if d == a or d == b or d == c: continue
                for e in range(n):
                    if e == a or e == b or e == c or e == d: continue
                    e1 = edge_vars[(a,b) if a<b else (b,a)]
                    e2 = edge_vars[(b,c) if b<c else (c,b)]
                    e3 = edge_vars[(c,d) if c<d else (d,c)]
                    e4 = edge_vars[(d,e) if d<e else (e,d)]
                    e5 = edge_vars[(e,a) if e<a else (a,e)]
                    solver.add(Not(And(e1, e2, e3, e4, e5)))
                    count += 1
print(f"Added {count} 5-cycle constraints")

# Color variables: each vertex gets 2 bits for 4 colors
color_vars = {}
for v in range(n):
    color_vars[(v,0)] = Bool(f'c_{v}_0')
    color_vars[(v,1)] = Bool(f'c_{v}_1')

# For each edge, colors must differ
for i in range(n):
    for j in range(i+1, n):
        e = edge_vars[(i,j)]
        # If edge exists, then colors differ
        # colors differ means (b1_i XOR b1_j) OR (b0_i XOR b0_j)
        # Implication: e => (b1_i != b1_j OR b0_i != b0_j)
        # Equivalent: Not(e) OR (b1_i != b1_j) OR (b0_i != b0_j)
        solver.add(Implies(e, Or(Xor(color_vars[(i,1)], color_vars[(j,1)]),
                                 Xor(color_vars[(i,0)], color_vars[(j,0)]))))

print("Added coloring constraints")
print("Solving...")

result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    edges = []
    for (i,j), var in edge_vars.items():
        if is_true(m[var]):
            edges.append((i,j))
    print(f"Number of edges: {len(edges)}")
    print(f"Edges: {edges}")

    # Verify girth
    adj = {v: set() for v in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = n+1
    for s in range(n):
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            v = queue.pop(0)
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    parent[w] = v
                    queue.append(w)
                elif w != parent[v]:
                    cycle_len = dist[v] + dist[w] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    print(f"Girth: {min_cycle}")

    colors = []
    for v in range(n):
        b1 = 1 if is_true(m[color_vars[(v,1)]]) else 0
        b0 = 1 if is_true(m[color_vars[(v,0)]]) else 0
        colors.append(b1*2 + b0)
    print(f"Colors: {colors}")
else:
    print("UNSAT")

