import random

n = 17
target_edges = 28

def has_short_cycle(adj, u, v):
    """Check if adding edge (u,v) creates a cycle of length <= 5"""
    # BFS from u to v, limited depth
    # We want to see if there's a path from u to v of length <= 4
    # (since adding edge would make cycle of length path_len+1)
    visited = {u: 0}
    queue = [u]
    while queue:
        node = queue.pop(0)
        if visited[node] >= 4:  # don't go beyond depth 4
            continue
        for w in adj[node]:
            if w == v:
                # Found path from u to v of length visited[node]+1
                # Cycle length would be visited[node]+2
                if visited[node] + 2 <= 5:
                    return True
            if w not in visited:
                visited[w] = visited[node] + 1
                queue.append(w)
    return False

def is_4_colorable(adj):
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for w in adj[v]:
            if colors[w] != -1:
                used.add(colors[w])
        for c in range(4):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

# Try many random constructions
best = 0
for trial in range(50000):
    adj = {v: set() for v in range(n)}
    edges = []

    # Try adding edges in random order
    all_pairs = [(i,j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_pairs)

    for u,v in all_pairs:
        if len(edges) >= target_edges:
            break
        if v in adj[u]:
            continue
        if not has_short_cycle(adj, u, v):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))

    if len(edges) > best:
        best = len(edges)
        print(f"Trial {trial}: {len(edges)} edges")

        if len(edges) >= target_edges:
            colorable, colors = is_4_colorable(adj)
            if colorable:
                print(f"FOUND! Edges: {len(edges)}")
                print(f"Edges: {edges}")
                print(f"Colors: {colors}")
                break
            else:
                print(f"  Not 4-colorable")

print(f"Best: {best}")
